def fr_typo(t):
  """French typography: no-break space inside guillemets and before : ; ? ! (no line break there)."""
  for a,b in (('« ','«\u00a0'),(' »','\u00a0»'),(' :','\u00a0:'),(' ;','\u00a0;'),(' ?','\u00a0?'),(' !','\u00a0!')):t=t.replace(a,b)
  return t
def emit(name,typename,d,path):
  keys=list(d.keys())
  for k,v in d.items(): assert len(v)==11,(k,len(v))
  lines=['// Generated from scripts/copy-src/linkedin_copy.py — edit there.',"import type {Dict} from '@/lib/i18n';",'export type '+typename+'={'+''.join(k+':string;' for k in keys)+'};','export const '+name+':Dict<'+typename+'>={']
  for i,l in enumerate(L):
    lines.append(' '+l+':{'+','.join(k+':'+json.dumps(fr_typo(d[k][i]) if l=='fr' else d[k][i],ensure_ascii=False) for k in keys)+'},')
  lines.append('};')
  open(path,'w').write('\n'.join(lines)+'\n')
emit('linkedinCopy','LinkedInCopy',ACC,'lib/copy/linkedin.ts')
emit('linkedinGuideCopy','LinkedInGuideCopy',GUIDE,'lib/copy/linkedin-guide.ts')
